+            when.is_some(), when.is_some_and(|when| when <= now),
+            when.map_or(0, |when| when.saturating_duration_since(now).as_micros()),
+            when.map_or(0, |when| now.saturating_duration_since(when).as_micros()));
+        let data = &self.spaces[SpaceId::Data];
+        let mut tracked_packets = 0usize;
+        let mut tracked_frames = 0usize;
+        let mut tracked_bytes = 0u64;
+        let mut oldest_age_us = 0u128;
+        for packet in data.sent_packets.values() {
+            let mut present = false;
+            for frame in &packet.stream_frames {
+                if frame.id == id {
+                    present = true;
+                    tracked_frames += 1;
+                    tracked_bytes += frame.offsets.end - frame.offsets.start;
+                }
+            }
+            if present {
+                tracked_packets += 1;
+                oldest_age_us = oldest_age_us.max(now.saturating_duration_since(packet.time_sent).as_micros());
