+    /// Diagnostic only: classify retained bytes without polling or changing range sets.
+    pub(super) fn diagnostic_send_state(&self) -> String {
+        let base = self.offset - self.unacked_len as u64;
+        let never_packetized = self.offset - self.unsent;
+        let selectively_acked: u64 = self.acks.iter().map(|range| range.end - range.start).sum();
+        let proto_sent_unacked = self.unsent.saturating_sub(base).saturating_sub(selectively_acked);
+        let prefix_end = self.acks.min().unwrap_or(self.unsent);
+        let prefix_retransmit: u64 = self.retransmits.iter().map(|range| {
+            range.end.min(prefix_end).saturating_sub(range.start.max(base))
+        }).sum();
+        let retransmit_raw: u64 = self.retransmits.iter().map(|range| range.end - range.start).sum();
+        let retransmit_unacked: u64 = self.retransmits.iter().map(|range| {
+            let start = range.start.max(base);
